print("verbatim G60-1732:", s["G60-1732"]["text"])
for x in r:
    if not x["in_scope"]: print("OOS:", x["verbatim_id"], x["out_of_scope_reason"], "|", s[x["verbatim_id"]]["text"][:200])
    if not x["signals"]: print("no signals:", x["verbatim_id"], s[x["verbatim_id"]]["channel"], "|", s[x["verbatim_id"]]["text"][:150])
# feedback type agreement vs BMW labels
m={"Likes":"like","Defect":"defect","Difficult to Use":"difficult_to_use","Wants":"want"}
agree=tot=0
for x in r:
    bmw={m.get(l["feedback_type"]) for l in s[x["verbatim_id"]]["bmw_labels"] if l["feedback_type"]}
    if not bmw: continue
    ours={sg["feedback_type"] for sg in x["signals"]}
    tot+=1; agree+= bool(bmw & ours)
print(f"feedback_type overlap with BMW labels: {agree}/{tot} verbatims")
import collections
print(collections.Counter(sg["category"] for x in r for sg in x["signals"]))
print(collections.Counter(sg["feedback_type"] for x in r for sg in x["signals"]))
EOF

